test("browse maps child signal exit to non-zero", async () => {
  const dir = mkdtempSync(join(tmpdir(), "cave-browse-signal-"));
  const stub = join(dir, "caveman-browse");
  writeFileSync(stub, "#!/bin/sh\nkill -TERM $$\n", { mode: 0o755 });
