export { stubAgent } from "./stub-agent.mjs";
export { nativeStub, nodeStub, stubEnv } from "./stub-bin.mjs";
export { stubUpstream } from "./stub-upstream.mjs";
export { stubControlApi } from "./stub-control-api.mjs";
export { runCli } from "./run-cli.mjs";

import { spawn } from "node:child_process";

export function runCli(cli, argv, { env = process.env, cwd, timeoutMs = 10_000 } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn("node", [cli, ...argv], { env, cwd });
    let stdout = "";
    let stderr = "";
    let settled = false;
    let timedOut = false;
    let deadlineTimer;
    let forceTimer;
    let hardStopTimer;

    const clearTimers = () => {
      clearTimeout(deadlineTimer);
      clearTimeout(forceTimer);
      clearTimeout(hardStopTimer);
    };
    const timeoutError = () => {
      const error = new Error(
        [
          `CLI timed out after ${timeoutMs}ms: ${argv.join(" ")}`,
          stdout ? `stdout:\n${stdout}` : "",
          stderr ? `stderr:\n${stderr}` : "",
        ]
          .filter(Boolean)
          .join("\n"),
      );
      error.stdout = stdout;
      error.stderr = stderr;
      return error;
    };
    const finish = (callback) => {
      if (settled) return;
      settled = true;
      clearTimers();
      callback();
    };

    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", (error) => finish(() => reject(error)));
    child.on("exit", (code) => {
      finish(() => {
        if (timedOut) reject(timeoutError());
        else resolve({ code, stdout, stderr });
      });
    });

    deadlineTimer = setTimeout(() => {
      timedOut = true;
      child.kill("SIGTERM");
      forceTimer = setTimeout(() => child.kill("SIGKILL"), 500);
      hardStopTimer = setTimeout(() => {
        child.unref();
        finish(() => reject(timeoutError()));
      }, 1_500);
    }, timeoutMs);
  });
}

#!/usr/bin/env node
import { createReadStream, statSync } from "node:fs";
import { createServer } from "node:http";
import { resolve, sep } from "node:path";

const root = resolve(process.argv[2] ?? "");
const port = Number(process.argv[3] ?? "8765");
if (!root || !Number.isInteger(port) || port <= 0) {
  throw new Error("usage: static-release-server.mjs <asset-root> [port]");
}

const server = createServer((request, response) => {
  if (request.method !== "GET" && request.method !== "HEAD") {
    response.writeHead(405).end();
    return;
  }
  const pathname = decodeURIComponent(new URL(request.url ?? "/", "http://release.invalid").pathname);
  const path = resolve(root, `.${pathname}`);
  if (path !== root && !path.startsWith(`${root}${sep}`)) {
    response.writeHead(403).end();
    return;
  }
  try {
    const stat = statSync(path);
    if (!stat.isFile()) throw new Error("not a file");
    response.writeHead(200, {
      "content-length": stat.size,
      "content-type": "application/octet-stream",
    });
    if (request.method === "HEAD") response.end();
    else createReadStream(path).pipe(response);
  } catch {
    response.writeHead(404).end();
  }
});

server.listen(port, "127.0.0.1", () => {
  process.stdout.write(`static release server listening on 127.0.0.1:${port}\n`);
});
process.on("SIGTERM", () => server.close(() => process.exit(0)));

