export function stubAgent({ dir, name = "claude", platform = process.platform }) {
  if (!dir) throw new Error("stubAgent requires dir");
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  // Windows cannot execute a shebang script: CreateProcess resolves through
  // PATHEXT, so an extensionless file is not spawnable at all (#834). Write the
  // body as .mjs and a .cmd shim under the bare name — which is exactly how a
  // real agent binary presents itself on PATH there, so the product still has
  // to resolve `name` through PATHEXT to find it.
  if (platform === "win32") {
    writeFileSync(join(dir, `${name}.mjs`), SOURCE);
    const path = join(dir, `${name}.cmd`);
    // The backslash after %~dp0 is load-bearing, not cosmetic: parseWindowsNodeShim
    // only recognizes a Node shim in the `"%~dp0\target.mjs" %*` form, so without
    // it portableInvocation throws "non-Node Windows command shim" and every test
    // that spawns through stubAgent fails on Windows. (%~dp0 already ends in a
    // separator; Windows collapses the double.)
    writeFileSync(path, [
      "@echo off",
      `node "%~dp0\\${name}.mjs" %*`,
      "exit /b %errorlevel%",
      "",
    ].join("\r\n"));
    return { dir, name, path };
  }
  const path = join(dir, name);
  writeFileSync(path, SOURCE, { mode: 0o755 });
  return { dir, name, path };
}

import { chmodSync, copyFileSync, linkSync, mkdirSync, writeFileSync } from "node:fs";
import { delimiter, join } from "node:path";

// Fake binaries have to be launchable the same way the real ones are, and
// Windows offers none of the POSIX shortcuts: there is no shebang, and Node
// refuses to spawn a .cmd/.bat without a shell (CVE-2024-27980), so neither an
// extensionless `#!/bin/sh` file nor a plain .cmd is spawnable by execFile.
//
// Two shapes exist here because the CLI launches things two ways:
//
//   nodeStub    for commands routed through portableInvocation (agent hosts
//               such as `pi`). On Windows that is a .cmd Node shim, which
//               portableInvocation unwraps into `node <target> <args>` — the
//               same shape npm/pnpm park on PATH.
//   nativeStub  for the Go binaries the CLI execFile's directly
//               (caveman-proxy, caveman-mcp). On Windows that must be a REAL
//               executable, so the stub is node.exe hardlinked under the
//               binary's name; the preload installed by stubEnv() answers and
//               exits before Node resolves argv[1] as a script. The product
//               spawns a native .exe, exactly as it does in production.
//
// Both shapes hand the stub body its arguments as `ARGV`, so one source string
// works on every platform. nodeStub bodies are ESM, nativeStub bodies are CJS —
// a Node preload cannot be an ES module.
const isWindows = process.platform === "win32";

const DISPATCH = `// Preloaded into every node process that inherits this env — including the CLI
// under test. It only acts when the running executable is one of the stubs.
const { basename, join } = require("node:path");
const { existsSync } = require("node:fs");
const stub = join(__dirname, basename(process.execPath, ".exe") + ".stub.cjs");
if (existsSync(stub)) {
  // Node resolved argv[1] against cwd on its way to treating it as a script;
  // basename gives the stub back the word the product actually passed.
  globalThis.__stubArgv = [basename(process.argv[1] ?? ""), ...process.argv.slice(2)];
  require(stub);
  process.exit(0);
}
`;

// A command the CLI launches through portableInvocation.
export function nodeStub(dir, name, source) {
  mkdirSync(dir, { recursive: true });
  const target = join(dir, `${name}.stub.mjs`);
  writeFileSync(target, `const ARGV = process.argv.slice(2);\n${source}`);
  if (!isWindows) {
    const path = join(dir, name);
    writeFileSync(path, `#!/bin/sh\nexec "${process.execPath}" "${target}" "$@"\n`, { mode: 0o755 });
    chmodSync(path, 0o755);
    return path;
  }
  const path = join(dir, `${name}.cmd`);
  // The `"%~dp0\<file>" %*` form is the only one parseWindowsNodeShim accepts.
  writeFileSync(path, ["@echo off", `node "%~dp0\\${name}.stub.mjs" %*`, "exit /b %errorlevel%", ""].join("\r\n"));
  return path;
}

// A binary the CLI execFile's directly. Requires stubEnv() for the child env.
export function nativeStub(dir, name, source) {
  mkdirSync(dir, { recursive: true });
  if (!isWindows) {
    const path = join(dir, name);
    writeFileSync(path, `#!/usr/bin/env node\nconst ARGV = process.argv.slice(2);\n${source}`, { mode: 0o755 });
    chmodSync(path, 0o755);
    return path;
  }
  writeFileSync(join(dir, `${name}.stub.cjs`), `const ARGV = globalThis.__stubArgv;\n${source}`);
  const path = join(dir, `${name}.exe`);
  // Hardlink, so no 100MB copy per fixture; falls back when node.exe and the
  // temp dir sit on different volumes.
  try { linkSync(process.execPath, path); } catch { copyFileSync(process.execPath, path); }
  return path;
}

// Puts `dir` on PATH (respecting the existing key's casing — a spread copy of
// process.env loses Windows' case-insensitivity, so setting "PATH" next to an
// inherited "Path" would leave two of them) and arms the nativeStub preload.
export function stubEnv(base, dir) {
  mkdirSync(dir, { recursive: true });
  const env = { ...base };
  const pathKey = Object.keys(env).find((key) => key.toLowerCase() === "path") ?? "PATH";
  env[pathKey] = `${dir}${delimiter}${env[pathKey] ?? ""}`;
  if (!isWindows) return env;
  const dispatch = join(dir, "stub-dispatch.cjs");
  writeFileSync(dispatch, DISPATCH);
  // Node parses NODE_OPTIONS itself, and inside a quoted value a backslash is
  // an escape character — a raw Windows path arrives with every separator
  // eaten (`C:UsersRUNNER~1AppData…`) and the preload never resolves. The
  // quotes still have to stay for a temp dir under a profile name with spaces,
  // so the separators are doubled rather than the quotes dropped.
  const quoted = `"${dispatch.replace(/\\/g, "\\\\")}"`;
  env.NODE_OPTIONS = `${env.NODE_OPTIONS ? `${env.NODE_OPTIONS} ` : ""}--require ${quoted}`;
  return env;
}

import { createServer } from "node:http";

function makeToken(org = "org-test") {
  const payload = Buffer.from(
    JSON.stringify({
      uid: "user-test",
      oid: org,
      email: "operator@example.test",
      role: "owner",
      exp: Math.floor(Date.now() / 1000) + 3600,
    }),
  ).toString("base64url");
  return `${payload}.sig`;
}

function listen(server) {
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      server.off("error", reject);
      resolve(server.address().port);
    });
  });
}

function close(server) {
  return new Promise((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
}

export async function stubControlApi({ seatWalled = false, organization = "org-test" } = {}) {
  const token = makeToken(organization);
  const requests = [];
  let meAuthHeader = null;

  const server = createServer((request, response) => {
    let rawBody = "";
    request.setEncoding("utf8");
    request.on("data", (chunk) => (rawBody += chunk));
    request.on("end", () => {
      const path = new URL(request.url ?? "/", "http://stub.invalid").pathname;
      const authorization = request.headers.authorization ?? null;
      requests.push({ method: request.method, path, body: rawBody, authorization });

      const send = (status, body) => {
        response.writeHead(status, { "content-type": "application/json" });
        response.end(JSON.stringify(body));
      };

      if (request.method === "POST" && path === "/api/v1/auth/device/code") {
        send(200, {
          device_code: "device-test",
          user_code: "CAVE-TEST",
          verification_uri: "http://stub.invalid/activate",
          verification_uri_complete: "http://stub.invalid/activate?user_code=CAVE-TEST",
          expires_in: 60,
          interval: 0,
        });
        return;
      }
      if (request.method === "POST" && path === "/api/v1/auth/device/token") {
        send(200, { access_token: token, token_type: "Bearer", expires_in: 900 });
        return;
      }
      if (request.method === "GET" && path === "/api/v1/auth/me") {
        if (authorization !== `Bearer ${token}`) {
          send(401, { error: { code: "cave_unauthorized" } });
          return;
        }
        meAuthHeader = authorization;
        send(200, { user: { email: "operator@example.test" } });
        return;
      }
      if (request.method === "POST" && path === "/api/v1/me/wrap-entitlement") {
        if (authorization !== `Bearer ${token}`) {
          send(401, { error: { code: "cave_unauthorized" } });
          return;
        }
        let body;
        try {
          body = JSON.parse(rawBody);
        } catch {
          send(400, { error: { code: "cave_invalid_json" } });
          return;
        }
        if (
          typeof body?.device_hash !== "string" ||
          !/^[a-f0-9]{64}$/.test(body.device_hash) ||
          typeof body?.device_name !== "string" ||
          body.device_name.trim() === ""
        ) {
          send(400, { error: { code: "cave_invalid_device" } });
          return;
        }
        if (seatWalled) {
          send(403, {
            error: {
              code: "cave_seats_exhausted",
              organization,
              plan: "free",
              seats_used: 1,
              seats_limit: 1,
            },
          });
          return;
        }
        send(200, {
          entitled: true,
          plan: "free",
          telemetry_level: "metadata",
          seats_used: 1,
          seats_limit: 1,
          devices_used: 1,
          devices_limit: 3,
          evicted_device_hash: null,
          expires_at: new Date(Date.now() + 72 * 3600 * 1000).toISOString(),
        });
        return;
      }
      send(404, { error: { code: "cave_not_found" } });
    });
  });

  const port = await listen(server);
  return {
    baseURL: `http://127.0.0.1:${port}`,
    token,
    requests,
    capturedAuth: () => meAuthHeader,
    close: () => close(server),
  };
}

import { createServer } from "node:http";

function listen(server) {
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      server.off("error", reject);
      resolve(server.address().port);
    });
  });
}

function close(server) {
  return new Promise((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
}

export async function stubUpstream() {
  const requests = [];
  const server = createServer((request, response) => {
    let rawBody = "";
    request.setEncoding("utf8");
    request.on("data", (chunk) => (rawBody += chunk));
    request.on("end", () => {
      const path = new URL(request.url ?? "/", "http://stub.invalid").pathname;
      if (request.method !== "POST" || path !== "/v1/messages") {
        response.writeHead(404, { "content-type": "application/json" });
        response.end(JSON.stringify({ error: { type: "not_found_error" } }));
        return;
      }

      let body;
      try {
        body = JSON.parse(rawBody);
      } catch {
        response.writeHead(400, { "content-type": "application/json" });
        response.end(JSON.stringify({ error: { type: "invalid_request_error" } }));
        return;
      }
      requests.push({ method: request.method, path, body });
      response.writeHead(200, { "content-type": "application/json" });
      response.end(
        JSON.stringify({
          id: "msg_stub",
          type: "message",
          role: "assistant",
          model: body.model ?? "claude-sonnet-4-6",
          content: [{ type: "text", text: "ok" }],
          stop_reason: "end_turn",
          stop_sequence: null,
          usage: {
            input_tokens: 12,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: 0,
            output_tokens: 2,
          },
        }),
      );
    });
  });

  const port = await listen(server);
  return {
    baseURL: `http://127.0.0.1:${port}`,
    requests,
    close: () => close(server),
  };
}

import { test } from "node:test";
import assert from "node:assert";
import { spawn, execFileSync, spawnSync } from "node:child_process";
import { chmodSync, copyFileSync, existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, delimiter } from "node:path";
import { createServer as createNetServer, connect } from "node:net";
import { fileURLToPath } from "node:url";
import { DatabaseSync } from "node:sqlite";

import { runCli, stubAgent, stubUpstream } from "./harness/index.mjs";

const cliDir = join(dirname(fileURLToPath(import.meta.url)), "..");
const cli = process.env.CAVEMAN_TEST_CLI ?? join(cliDir, "dist", "index.js");
const packageParent = join(cliDir, "..");
const publicRoot = existsSync(join(packageParent, "proxy")) ? packageParent : join(packageParent, "..");
const goToolchainAvailable = spawnSync("go", ["version"], { stdio: "ignore" }).status === 0;

function freePort() {
  return new Promise((resolve, reject) => {
    const server = createNetServer();
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      const port = server.address().port;
      server.close((error) => (error ? reject(error) : resolve(port)));
    });
  });
}

async function waitForPort(port, timeoutMs = 5_000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const ready = await new Promise((resolve) => {
      const socket = connect({ host: "127.0.0.1", port });
      socket.once("connect", () => {
        socket.destroy();
        resolve(true);
      });
      socket.once("error", () => resolve(false));
    });
    if (ready) return;
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
  throw new Error(`port ${port} did not become ready`);
}

function waitForExit(child, timeoutMs) {
  return new Promise((resolve) => {
    if (child.exitCode !== null || child.signalCode !== null) return resolve(true);
    const onExit = () => {
      clearTimeout(timer);
      resolve(true);
    };
    const timer = setTimeout(() => {
      child.off("exit", onExit);
      resolve(false);
    }, timeoutMs);
    child.once("exit", onExit);
  });
}

async function stopChild(child) {
  if (child.exitCode !== null || child.signalCode !== null) return;
  child.kill("SIGTERM");
  if (await waitForExit(child, 1_500)) return;
  child.kill("SIGKILL");
  await waitForExit(child, 1_500);
}

test("real proxy wraps stub agent through stub upstream and records SQLite telemetry", async (t) => {
  if (!process.env.CAVEMAN_TEST_PROXY_BIN && !goToolchainAvailable) return t.skip("go toolchain not found");
  const upstream = await stubUpstream();
  const home = mkdtempSync(join(tmpdir(), "cave-agent-home-"));
  const caveHome = mkdtempSync(join(tmpdir(), "cave-agent-store-"));
  const binDir = mkdtempSync(join(tmpdir(), "cave-agent-bin-"));
  const proxyBin = join(binDir, "caveman-proxy");
  let proxy = null;
  try {
    const proxyPort = await freePort();
    const agent = stubAgent({ dir: binDir });
    if (process.env.CAVEMAN_TEST_PROXY_BIN) {
      copyFileSync(process.env.CAVEMAN_TEST_PROXY_BIN, proxyBin);
      chmodSync(proxyBin, 0o755);
    } else {
      execFileSync("go", ["build", "-o", proxyBin, "./proxy/cmd/caveman-proxy"], {
        cwd: publicRoot,
        stdio: "pipe",
      });
    }
    mkdirSync(caveHome, { recursive: true });
    const configPath = join(caveHome, "caveman.yaml");
    writeFileSync(
      configPath,
      [
        "mode: record",
        `listen: 127.0.0.1:${proxyPort}`,
        "providers:",
        "  anthropic:",
        `    base_url: ${upstream.baseURL}`,
        "",
      ].join("\n"),
    );

    const proxyEnv = {
      ...process.env,
      CAVEMAN_HOME: caveHome,
      CAVEMAN_CONFIG: configPath,
      CAVE_SSRF_ALLOWLIST: "127.0.0.1",
      CAVEMAN_TELEMETRY: "0",
    };
    proxy = spawn(proxyBin, ["serve"], { env: proxyEnv, stdio: ["ignore", "pipe", "pipe"] });
    proxy.stdout.resume();
    proxy.stderr.resume();

    await waitForPort(proxyPort);
    const env = {
      ...proxyEnv,
      HOME: home,
      CAVE_GATEWAY_URL: `http://127.0.0.1:${proxyPort}`,
      CAVEMAN_PROXY_BIN: proxyBin,
      PATH: `${agent.dir}${delimiter}${process.env.PATH}`,
      CAVE_NO_KEYCHAIN: "1",
      NO_COLOR: "1",
    };
    const wrapped = await runCli(cli, ["wrap", agent.name], { env });
    assert.equal(wrapped.code, 0, wrapped.stderr);
    assert.match(wrapped.stdout, /stub-agent: ok/);
    assert.equal(upstream.requests.length, 1);
    assert.equal(upstream.requests[0].path, "/v1/messages");
    assert.equal(upstream.requests[0].body.model, "claude-sonnet-4-6");

    const db = new DatabaseSync(join(caveHome, "caveman.db"), { readOnly: true });
    try {
      const query = db.prepare(
        "SELECT provider, model, status_code, input_tokens, output_tokens, token_usage_basis FROM requests ORDER BY id",
      );
      const deadline = Date.now() + 2_000;
      let rows = query.all();
      while (rows.length === 0 && Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, 25));
        rows = query.all();
      }
      assert.equal(rows.length, 1);
      const row = rows[0];
      assert.equal(row.provider, "anthropic");
      assert.equal(row.model, "claude-sonnet-4-6");
      assert.equal(Number(row.status_code), 200);
      assert.equal(Number(row.input_tokens), 12);
      assert.equal(Number(row.output_tokens), 2);
      assert.equal(row.token_usage_basis, "provider_complete");
    } finally {
      db.close();
    }
  } finally {
    if (proxy) await stopChild(proxy);
    try {
      await upstream.close();
    } finally {
      for (const dir of [home, caveHome, binDir]) {
        rmSync(dir, { recursive: true, force: true });
      }
    }
  }
});

