    CAVEMAN_MCP_BIN: "/nonexistent/caveman-mcp",
    CAVE_GATEWAY_URL: gatewayUrl,
    PATH: `${binDir}:${process.env.PATH}`,
  };
  clearHermesKeys(env);
  return { ...env, ...extra };
}

