import { test } from "node:test";
import assert from "node:assert";
import { spawn } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const cli = join(dirname(fileURLToPath(import.meta.url)), "..", "dist", "index.js");

function runSetup(env) {
  return new Promise((resolve, reject) => {
    // node is invoked by absolute path so an empty PATH can't break the spawn.
    const child = spawn(process.execPath, [cli, "setup"], { env });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    child.on("exit", (code) => resolve({ code, stdout, stderr }));
    child.on("error", reject);
  });
}

// baseEnv makes binary resolution deterministic: empty PATH, an empty
// CAVEMAN_HOME, and no CAVEMAN_*_BIN overrides leaking in from the host.
function baseEnv(home) {
  const env = { ...process.env, NO_COLOR: "1", PATH: "", CAVEMAN_HOME: home };
  for (const k of ["CAVEMAN_PROXY_BIN", "CAVEMAN_ENGINE_BIN", "CAVEMAN_MCP_BIN", "CAVEMEM_BIN", "CAVEMAN_BROWSE_BIN", "CAVEMAN_SHRINK_BIN"]) delete env[k];
  return env;
}

// A fresh npm install has none of the Go binaries. `caveman setup` must make
// that impossible to miss: name every missing binary, say what degrades (loud
// byte-safe pass-through, savings honestly 0), show the one install command,
// and exit non-zero so scripts can gate on it. (no-fake-savings)
test("setup reports every missing binary, the install command, and exits non-zero", async () => {
  const home = mkdtempSync(join(tmpdir(), "cave-setup-empty-"));
  const out = await runSetup(baseEnv(home));
  assert.notEqual(out.code, 0, "missing required binaries must exit non-zero");
  for (const name of ["caveman-proxy", "caveman-engine", "caveman-mcp", "cavemem", "caveman-browse", "caveman-shrink"]) {
    assert.match(out.stdout, new RegExp(name), `must name ${name}`);
  }
  assert.match(out.stdout, /missing/i);
  assert.match(out.stdout, /pass-through/i, "must say affected commands degrade to pass-through");
  assert.match(out.stdout, /agent-side compressed browsing MCP tools/, "browse line must say what installing it unlocks");
  assert.match(out.stdout, /wrap auto-registers once installed/, "browse line must say wrap auto-registers it once present");
  assert.match(out.stdout, /caveman setup --install/, "must show the signed install command");
  assert.match(out.stdout, /login/, "must say connected verbs still work");
});

// With binaries present in ~/.caveman/bin (where the install script builds
// them), setup must show where each resolved from and exit 0.
test("setup finds binaries in ~/.caveman/bin and exits 0", async () => {
  const home = mkdtempSync(join(tmpdir(), "cave-setup-full-"));
  const binDir = join(home, "bin");
  mkdirSync(binDir, { recursive: true });
  for (const name of ["caveman-proxy", "caveman-engine", "caveman-mcp", "cavemem", "caveman-browse", "caveman-shrink"]) {
    writeFileSync(join(binDir, name), "#!/bin/sh\nexit 0\n", { mode: 0o755 });
  }
  const out = await runSetup(baseEnv(home));
  assert.equal(out.code, 0, `all binaries present must exit 0: ${out.stdout}${out.stderr}`);
  assert.match(out.stdout, /All required binaries found/);
  assert.match(out.stdout, new RegExp(binDir.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")), "must print the resolved path");
});

// Optional browse and tool-catalog binaries must not fail gate: required-only present → 0.
test("setup treats caveman-browse and caveman-shrink as optional", async () => {
  const home = mkdtempSync(join(tmpdir(), "cave-setup-req-"));
  const binDir = join(home, "bin");
  mkdirSync(binDir, { recursive: true });
  for (const name of ["caveman-proxy", "caveman-engine", "caveman-mcp", "cavemem"]) {
    writeFileSync(join(binDir, name), "#!/bin/sh\nexit 0\n", { mode: 0o755 });
  }
  const out = await runSetup(baseEnv(home));
  assert.equal(out.code, 0, `browse alone missing must still exit 0: ${out.stdout}`);
  assert.match(out.stdout, /caveman-browse\s+missing\s+\(optional\)/, "browse must be marked optional");
  assert.match(out.stdout, /caveman-shrink\s+missing\s+\(optional\)/, "shrink must be marked optional");
});

import { test } from "node:test";
import assert from "node:assert";
import { spawn } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const cli = join(here, "..", "dist", "index.js");

// run spawns the built CLI with the given args and returns its exit code + streams.
function run(args, env) {
  return new Promise((resolve, reject) => {
    const child = spawn("node", [cli, ...args], { env });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    child.on("exit", (code) => resolve({ code, stdout, stderr }));
    child.on("error", reject);
  });
}

// A stub engine that emits a fixed compressed marker on stdout and a JSON report
// (with a recovery handle) on stderr — standing in for the real caveman-engine.
function compressStub() {
  const dir = mkdtempSync(join(tmpdir(), "cave-engine-"));
  const bin = join(dir, "caveman-engine");
  writeFileSync(
    bin,
    `#!/bin/sh\ncat >/dev/null\nprintf 'SHRUNK'\nprintf '{"tokens_before":100,"tokens_after":10,"ratio":0.9,"basis":"inferred","token_count_basis":"o200k_base","recovery_handle":"ccr_test123"}' 1>&2\n`,
    { mode: 0o755 },
  );
  return bin;
}

// shrink wraps a command, captures its output, runs it through the engine, forwards
// the compressed stdout, appends a recovery footer with the handle, and — crucially —
// propagates the wrapped command's exit code so an agent still sees the failure.
test("shrink wraps a command, appends a recovery footer, and propagates the exit code", async () => {
  const out = await run(
    ["shrink", "--", "node", "-e", "process.stdout.write('RAWOUT'); process.exit(7)"],
    { ...process.env, CAVEMAN_ENGINE_BIN: compressStub() },
  );
  assert.equal(out.code, 7, "shrink must propagate the wrapped command's exit code");
  assert.match(out.stdout, /SHRUNK/, "shrink must forward the engine's compressed stdout");
  assert.match(out.stdout, /recover: caveman retrieve ccr_test123/, "shrink must append a recovery footer carrying the handle");
  assert.match(out.stdout, /100→10 estimated tokens/, "token counters must be labeled as estimates");
  assert.match(out.stdout, /counter o200k_base · inferred/, "footer must disclose counter and evidence basis");
});

// With the engine unavailable, shrink must fail open: print the wrapped command's
// original output unchanged, with no footer, and still propagate its exit code.
test("shrink falls back to byte-safe pass-through when the engine is missing", async () => {
  const out = await run(
    ["shrink", "--", "node", "-e", "process.stdout.write('hello-original'); process.exit(3)"],
    { ...process.env, CAVEMAN_ENGINE_BIN: "caveman-engine-does-not-exist" },
  );
  assert.equal(out.code, 3, "exit code must still propagate on fallback");
  assert.equal(out.stdout, "hello-original", "fallback must emit the captured output unchanged");
  assert.doesNotMatch(out.stdout, /caveman retrieve/, "fallback must not claim a recovery handle it never minted");
});

// --raw bypasses the engine entirely: the original output passes through even when a
// (mangling) engine is configured.
test("shrink --raw bypasses the engine", async () => {
  const out = await run(
    ["shrink", "--raw", "--", "node", "-e", "process.stdout.write('RAWOUT')"],
    { ...process.env, CAVEMAN_ENGINE_BIN: compressStub() },
  );
  assert.equal(out.code, 0);
  assert.equal(out.stdout, "RAWOUT", "--raw must pass the original output through unchanged");
  assert.doesNotMatch(out.stdout, /SHRUNK/, "--raw must not invoke the engine");
});

// retrieve shells out to the engine's retrieve subcommand, forwarding its stdout
// (the recovered original) and exit code.
test("retrieve forwards the engine's recovered bytes and exit code", async () => {
  const dir = mkdtempSync(join(tmpdir(), "cave-engine-retrieve-"));
  const bin = join(dir, "caveman-engine");
  writeFileSync(bin, `#!/bin/sh\n# retrieve <handle> [query]\nprintf 'ORIGINAL-BYTES'\n`, { mode: 0o755 });
  const out = await run(["retrieve", "ccr_test123"], { ...process.env, CAVEMAN_ENGINE_BIN: bin });
  assert.equal(out.code, 0);
  assert.equal(out.stdout, "ORIGINAL-BYTES", "retrieve must forward the engine's recovered bytes");
});

// retrieve with no handle is a usage error (exit 2), never a silent success.
test("retrieve requires a handle", async () => {
  const out = await run(["retrieve"], { ...process.env });
  assert.equal(out.code, 2);
  assert.match(out.stderr, /usage: caveman retrieve/);
});

import { test } from "node:test";
import assert from "node:assert";
import { spawn } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { delimiter, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const cli = join(here, "..", "dist", "index.js");

function runAdd(project, args, extraEnv = {}) {
  const env = { ...process.env, NO_COLOR: "1", ...extraEnv };
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [cli, "skills", "add", ...args], { cwd: project, env });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (data) => (stdout += data));
    child.stderr.on("data", (data) => (stderr += data));
    child.on("exit", (code) => resolve({ code, stdout, stderr, output: stdout + stderr }));
    child.on("error", reject);
    child.stdin.end();
  });
}

function writeFakeNpx() {
  const dir = mkdtempSync(join(tmpdir(), "cave-skills-npx-"));
  const bin = join(dir, "npx");
  writeFileSync(bin, `#!/usr/bin/env node
import { mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
const args = process.argv.slice(2);
if (process.env.NPX_ARGS_FILE) writeFileSync(process.env.NPX_ARGS_FILE, JSON.stringify(args));
if (process.env.NPX_EXIT) process.exit(Number(process.env.NPX_EXIT));
if (args.includes("--list") || args.includes("-l")) {
  console.log("tdd");
  process.exit(0);
}
const global = args.includes("--global") || args.includes("-g");
const root = args.includes("claude-code")
  ? join(global ? homedir() : process.cwd(), ".claude", "skills")
  : join(global ? homedir() : process.cwd(), ".agents", "skills");
const skill = join(root, "tdd");
mkdirSync(join(skill, "references"), { recursive: true });
writeFileSync(join(skill, "SKILL.md"), \`---
name: tdd
description: Test-drive code changes.
---

# TDD

\${"Write one failing test, then make it pass.\\n".repeat(500)}\`);
writeFileSync(join(skill, "references", "notes.md"), "resource stays plain and untouched\\n");
`, { mode: 0o755 });
  return { dir, bin };
}

function writeEngineStub() {
  const dir = mkdtempSync(join(tmpdir(), "cave-skills-add-engine-"));
  const bin = join(dir, "caveman-engine");
  writeFileSync(bin, `#!/usr/bin/env node
import { writeFileSync } from "node:fs";
const file = process.argv[5];
if (process.argv[2] !== "pixel" || process.argv[3] !== "render" || process.argv[4] !== "--dense" || !file) process.exit(2);
writeFileSync(file + ".px1.png", Buffer.from("png"));
console.log(JSON.stringify({ width: 10, height: 10, charsRendered: 10, droppedChars: 0, estTokens: 400 }));
console.log(JSON.stringify({ summary: true, pages: 1, textEstTokens: 5000, imageEstTokens: 400 }));
`, { mode: 0o755 });
  return bin;
}

function fakePath(fakeNpxDir) {
  return [fakeNpxDir, process.env.PATH ?? ""].join(delimiter);
}

test("skills add forwards Skills CLI source/options and pixelizes only installed skill", async () => {
  const project = mkdtempSync(join(tmpdir(), "cave-skills-add-project-"));
  const existing = join(project, ".agents", "skills", "existing");
  mkdirSync(existing, { recursive: true });
  const existingBody = `---\nname: existing\ndescription: Leave this skill alone.\n---\n\nExisting body.\n`;
  writeFileSync(join(existing, "SKILL.md"), existingBody);
  const sameNameOtherAgent = join(project, ".claude", "skills", "tdd");
  mkdirSync(sameNameOtherAgent, { recursive: true });
  const otherAgentBody = `---\nname: tdd\ndescription: Existing Claude-only variant.\n---\n\nDo not rewrite me.\n`;
  writeFileSync(join(sameNameOtherAgent, "SKILL.md"), otherAgentBody);
  const fake = writeFakeNpx();
  const argsFile = join(project, "npx-args.json");
  const engine = writeEngineStub();

  const out = await runAdd(
    project,
    ["mattpocock/skills", "--skill", "tdd", "--agent", "codex", "-y"],
    { PATH: fakePath(fake.dir), NPX_ARGS_FILE: argsFile, CAVEMAN_ENGINE_BIN: engine },
  );
  assert.equal(out.code, 0, out.output);
  assert.deepEqual(JSON.parse(readFileSync(argsFile, "utf8")), [
    "--yes", "skills", "add", "mattpocock/skills", "--skill", "tdd", "--agent", "codex", "-y", "--copy",
  ]);

  const installed = join(project, ".agents", "skills", "tdd");
  const stub = readFileSync(join(installed, "SKILL.md"), "utf8");
  assert.match(stub, /<!-- caveman-pixel v1 sha256:[a-f0-9]{64} -->/);
  assert.ok(existsSync(join(installed, "SKILL.px1.png")));
  assert.match(readFileSync(join(installed, "SKILL.orig.md"), "utf8"), /^---\nname: tdd\n/);
  assert.equal(readFileSync(join(installed, "references", "notes.md"), "utf8"), "resource stays plain and untouched\n");
  assert.equal(readFileSync(join(existing, "SKILL.md"), "utf8"), existingBody, "unrelated installed skill must stay untouched");
  assert.equal(readFileSync(join(sameNameOtherAgent, "SKILL.md"), "utf8"), otherAgentBody, "same-name skill in unchanged agent root must stay untouched");
  assert.match(out.output, /tdd: 5000 → 520 est tokens \(−90% inferred\)/);
  assert.match(out.output, /not security-reviewed by Caveman/);
});

test("skills add preserves upstream exit code and does not claim installation", async () => {
  const project = mkdtempSync(join(tmpdir(), "cave-skills-add-fail-"));
