if (process.argv[2] === "status") { process.stdout.write('{"owner":"unknown"}'); process.exit(0); }
const url = new URL(process.env.CAVE_GATEWAY_URL);
writeFileSync(${JSON.stringify(modeFile)}, JSON.stringify({
